#!/usr/bin/env python3
"""SEN0414 chapter 6 - builds question_bank_v2_0_0.json from the compact specification below (version 1.0.0).

Each Apply item is a program whose real output is computed here (python3.14) and must equal the stated correct option; the
distractors are written by hand as the plausible wrong readings. Answer positions are assigned from a balanced cycle so that each
of the four positions holds 20-30 per cent of the bank (the checker's rule). Run: python3 question_bank_make_v2_0_0.py
The bank itself is then checked by question_bank_check_v2_0_0.py (chapter 5 checker question_bank_check_v1_2_0.py, copied into this folder).
"""
__version__ = "2.0.0"
import json, os, subprocess, sys
PY = "/root/.local/bin/python3.14"
ITEMS = []


import importlib.util
_spec = importlib.util.spec_from_file_location("corpus6", os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "sen0414_ch06_corpus_v1_0_0.py"))
_C = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(_C)
_LABEL = {n[0]: n[1] for n in _C.NODES}
_SEEN = {}


def A(concept, q, code, right, wrong, why):
    # the stem names the concept (the checker refuses a stem shared by two items); a concept's later programs say which one
    _SEEN[concept] = _SEEN.get(concept, 0) + 1
    nth = ["", " second", " third", " fourth"][_SEEN[concept] - 1]
    if q == "What does this program print?":
        q = "%s: what does this%s program print?" % (_LABEL[concept], nth)
    ITEMS.append(dict(concept=concept, level="Apply", q=q, code=code, right=right, wrong=wrong, why=why))


def U(concept, level, q, right, wrong, why):
    ITEMS.append(dict(concept=concept, level=level, q=q, right=right, wrong=wrong, why=why))


