def build():
    out = []
    # balanced cycle of answer positions: blocks of eight with each position twice, blocks permuted
    cyc = [0, 1, 2, 3, 2, 3, 0, 1, 1, 0, 3, 2, 3, 2, 1, 0]
    for k, it in enumerate(ITEMS):
        pos = cyc[k % len(cyc)]
        opts = list(it["wrong"]); opts.insert(pos, it["right"])
        d = dict(concept=it["concept"], level=it["level"], q=it["q"])
        if it["level"] == "Apply":
            d["code"] = it["code"]
        d.update(options=opts, answer=pos, why=it["why"])
        out.append(d)
    return out


if __name__ == "__main__":
    bank = build(); bad = 0
    for it in ITEMS:
        if it["level"] != "Apply":
            continue
        r = subprocess.run([PY, "-c", it["code"]], capture_output=True, text=True, stdin=subprocess.DEVNULL, timeout=20)
        got = r.stdout.strip() if r.returncode == 0 else [l for l in r.stderr.strip().splitlines() if l.strip()][-1].split(":")[0]
        if got != it["right"]:
            bad += 1; print("MISMATCH", it["concept"], repr(got), "!=", repr(it["right"]))
    here = os.path.dirname(os.path.abspath(__file__))
    json.dump(bank, open(os.path.join(here, "question_bank_v2_0_0.json"), "w"), indent=1, ensure_ascii=False)
    print(len(bank), "items written;", sum(1 for i in bank if i["level"] == "Apply"), "Apply programs run;", bad, "mismatches")
